        vm.label(WBNB_TOKEN, "WBNB");

        address[] memory components = ICKTokenCook(CK_TOKEN).getComponents();
        for (uint256 i = 0; i < components.length; i++) {
            vm.label(components[i], string(abi.encodePacked("CK component ", vm.toString(i))));
        }
