    function _safeTransferAll(
        address token,
        address to
    ) private {
        uint256 amount = IERC20(token).balanceOf(address(this));
        if (amount == 0) return;

        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(IERC20.transfer.selector, to, amount));
