    ) external;
}

interface IPancakeInfinityVault {
    function lock(
        bytes calldata data
    ) external returns (bytes memory result);
    function take(
        address currency,
        address to,
        uint256 amount
    ) external;
    function sync(
        address currency
    ) external;
    function settle() external payable returns (uint256 paid);
}

interface IPolVault {
